CREATE TABLE IF NOT EXISTS cohort_summary (
    cohort TEXT PRIMARY KEY,
    cohort_size INTEGER NOT NULL,
    example_comment TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO cohort_summary (cohort, cohort_size, example_comment)
SELECT cohort, COUNT(*) as cohort_size, MIN(contact_notes) as example_comment
FROM participants
GROUP BY cohort;
